<?php require 'helpers.php'; $id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT c.*,u.name AS leader_name FROM clubs c JOIN users u ON u.id=c.leader_id WHERE c.id=?');$q->execute([$id]);$club=$q->fetch();if(!$club){http_response_code(404);exit('Club not found.');}$pageTitle=$club['name'];
if($_SERVER['REQUEST_METHOD']==='POST'){require_login();if(current_user()['role']!=='student'){flash('Only student accounts can join clubs.','error');redirect('club.php?id='.$id);} $q=$pdo->prepare('INSERT IGNORE INTO memberships(user_id,club_id) VALUES(?,?)');$q->execute([current_user()['id'],$id]);flash($q->rowCount()?'You joined this club!':'You are already a member.');redirect('club.php?id='.$id);}
require 'header.php';$q=$pdo->prepare('SELECT COUNT(*) FROM memberships WHERE club_id=?');$q->execute([$id]);$members=$q->fetchColumn();$joined=false;if(is_logged_in()){$q=$pdo->prepare('SELECT id FROM memberships WHERE user_id=? AND club_id=?');$q->execute([current_user()['id'],$id]);$joined=(bool)$q->fetch();}$q=$pdo->prepare('SELECT * FROM events WHERE club_id=? AND event_date>=NOW() ORDER BY event_date');$q->execute([$id]);$events=$q->fetchAll(); ?>
<section class="page-intro"><span class="eyebrow"><?=e($club['category']?:'STUDENT CLUB')?></span><h1><?=e($club['name'])?></h1><p><?=e($club['description'])?></p><p class="muted">Club leader: <?=e($club['leader_name'])?> · <?=$members?> members</p><?php if(is_logged_in() && current_user()['role']==='student'): ?><form method="post"><?php csrf_field(); ?><button class="btn <?= $joined?'ghost':'primary' ?>"><?=$joined?'Already a member':'Join this club'?></button></form><?php elseif(!is_logged_in()): ?><a class="btn primary" href="login.php">Log in to join</a><?php endif; ?></section>
<section class="section-head"><div><span class="eyebrow">WHAT'S HAPPENING</span><h2>Club events</h2></div></section><div class="cards"><?php if(!$events): ?><div class="empty">No upcoming events for this club.</div><?php endif; ?><?php foreach($events as $ev): ?><article class="event-card"><div class="event-date"><b><?=date('d',strtotime($ev['event_date']))?></b><span><?=date('M',strtotime($ev['event_date']))?></span></div><div><h3><?=e($ev['title'])?></h3><p><?=e($ev['venue'])?></p><a class="text-link" href="event.php?id=<?=$ev['id']?>">View event →</a></div></article><?php endforeach; ?></div>
<?php require 'footer.php'; ?>
